import javax.swing.JMenu;
import javax.swing.JMenuBar;

public class MenuTreePanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            MenuTreePanel panel = new MenuTreePanel();
            panel.addMenu("File");
            panel.addMenu("Edit");
            panel.addItem("File", "New");
            panel.addItem("File", "Open");
            panel.addItem("File", "Save");
            panel.addItem("Edit", "Copy");
            panel.addItem("Edit", "Paste");
            panel.addItem("View", "Zoom");

            JMenuBar bar = panel.getMenuBar();

            check("two menus on the bar", 2, bar.getMenuCount());
            check("walking the bar down to one item", "File/Save",
                    bar.getMenuCount() > 0 && bar.getMenu(0).getItemCount() > 2
                            ? bar.getMenu(0).getText() + "/" + bar.getMenu(0).getItem(2).getText()
                            : "not there");
            check("itemCount(File)", 3, panel.itemCount("File"));
            check("itemCount(Edit)", 2, panel.itemCount("Edit"));
            check("an item added to a missing menu is dropped", -1, panel.itemCount("View"));
            check("pathOf an item in the first menu", "File > Save", panel.pathOf("Save"));
            check("pathOf an item in the second menu", "Edit > Paste", panel.pathOf("Paste"));
            check("pathOf an item nobody holds", null, panel.pathOf("Zoom"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

