import javax.swing.JMenu;
import javax.swing.JMenuBar;
import javax.swing.JMenuItem;
import javax.swing.JPanel;

public class MenuTreePanel extends JPanel {

    private final JMenuBar bar = new JMenuBar();

    public MenuTreePanel() {
        bar.setName("bar");
        add(bar);
    }

    public JMenuBar getMenuBar() {
        return bar;
    }

    public void addMenu(String title) {
        bar.add(new JMenu(title));
    }

    public void addItem(String menuTitle, String itemText) {
        JMenu menu = menuNamed(menuTitle);
        if (menu != null) {
            menu.add(new JMenuItem(itemText));
        }
    }

    public int itemCount(String menuTitle) {
        JMenu menu = menuNamed(menuTitle);
        return menu == null ? -1 : menu.getItemCount();
    }

    public String pathOf(String itemText) {
        for (int i = 0; i < bar.getMenuCount(); i++) {
            JMenu menu = bar.getMenu(i);
            for (int j = 0; j < menu.getItemCount(); j++) {
                JMenuItem item = menu.getItem(j);
                if (item != null && itemText.equals(item.getText())) {
                    return menu.getText() + " > " + item.getText();
                }
            }
        }
        return null;
    }

    private JMenu menuNamed(String title) {
        for (int i = 0; i < bar.getMenuCount(); i++) {
            JMenu menu = bar.getMenu(i);
            if (menu != null && menu.getText().equals(title)) {
                return menu;
            }
        }
        return null;
    }
}
